def clean(df):
    d = df.copy()
    # drop exact duplicate rows
    d = d.drop_duplicates()
    # normalize Category label variants (e.g. 'Furnture' -> 'Furniture')
    cat_map = {
        'electronics': 'Electronics',
        'accessories': 'Accessories',
        'furniture': 'Furniture',
        'furnture': 'Furniture',
        'office supplies': 'Office Supplies',
    }
    d['Category'] = (d['Category'].astype(str).str.strip()
                     .map(lambda v: cat_map.get(v.lower(), v) if v not in ('nan', 'None') else v))
    # normalize Region whitespace/case variants (not used in the answer, but tidy)
    reg_map = {'north': 'North', 'south': 'South', 'east': 'East', 'west': 'West'}
    d['Region'] = d['Region'].apply(
        lambda v: reg_map.get(str(v).strip().lower(), str(v).strip())
        if pd.notna(v) else v)
    # ensure numeric columns are numeric
    for c in ['Quantity', 'Price', 'Revenue', 'Order_ID']:
        if c in d.columns:
            d[c] = pd.to_numeric(d[c], errors='coerce')
    return d


def answer(df):
    d = clean(df)
    d = d.dropna(subset=['Category', 'Price'])
    g = d.groupby('Category')['Price'].mean()
    return {str(k): float(v) for k, v in g.items()}
